sys_script.script:
(function () {
    var cumulativeScore = parseFloat(current.getValue('cumulative_score')) || 0;
    var thresholdScore = parseFloat(current.getValue('threshold_score')) || 0;
    var currentStatus = current.getValue('status');

    // Don't change status if score is 0 (likely just created or no ratings yet)
    if (cumulativeScore === 0) {
        return;
    }

    // If score is below threshold and not already blacklisted
    if (cumulativeScore < thresholdScore && currentStatus !== 'blacklisted') {
        current.setValue('status', 'under_review');
        gs.addInfoMessage('Warning: Supplier score has fallen below threshold. Status changed to Under Review.');
    }
})();
